import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  computed,
  ElementRef,
  inject,
  input,
  linkedSignal,
  OnDestroy,
  ViewEncapsulation,
} from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatMenuModule } from '@angular/material/menu';
import { RouterLink, RouterLinkWithHref } from '@angular/router';
import { TranslatePipe } from '@ngx-translate/core';

/**
 * Base data representing a single breadcrumb item.
 *
 * This is the foundation interface for all breadcrumb items, containing the minimum
 * required properties. Items of this type represent non-clickable breadcrumb entries,
 * typically used for the current page or inactive navigation states.
 *
 * The last breadcrumb item can optionally not be a link to represent the current page.
 * In that case, the `href` or `routerLink` property should be omitted.
 *
 * @example
 * ```typescript
 * const currentPageItem: SatBreadcrumbsItemBase = {
 *   label: 'Current Page'
 * };
 * ```
 */
export interface SatBreadcrumbsItemBase {
  /** The label text to display in the breadcrumb item. */
  label: string;
}

/**
 * Breadcrumb item that navigates to a specific URL using standard HTML anchor navigation.
 *
 * This interface extends the base breadcrumb item to include an `href` property for
 * traditional web navigation. Use this type when you want to navigate to external URLs
 * or when you prefer standard anchor tag behavior over Angular's router navigation.
 *
 * @example
 * ```typescript
 * const externalLinkItem: SatBreadcrumbsItemWithHref = {
 *   label: 'External Site',
 *   href: 'https://example.com'
 * };
 *
 * const internalLinkItem: SatBreadcrumbsItemWithHref = {
 *   label: 'Documentation',
 *   href: '/docs'
 * };
 * ```
 */
export interface SatBreadcrumbsItemWithHref extends SatBreadcrumbsItemBase {
  /** The URL to navigate to when the breadcrumb item is clicked. */
  href: string;
}

/**
 * Breadcrumb item that navigates using Angular's Router for SPA navigation.
 *
 * This interface extends the base breadcrumb item to include Angular Router navigation
 * properties. Use this type when you want to leverage Angular's routing capabilities,
 * including route parameters, query parameters, and programmatic navigation within
 * your single-page application.
 *
 * @example
 * ```typescript
 * const routerLinkItem: SatBreadcrumbsItemWithRouterLink = {
 *   label: 'User Profile',
 *   routerLink: ['/user', userId],
 *   queryParams: { tab: 'settings' }
 * };
 *
 * const simpleRouteItem: SatBreadcrumbsItemWithRouterLink = {
 *   label: 'Dashboard',
 *   routerLink: '/dashboard'
 * };
 * ```
 */
export interface SatBreadcrumbsItemWithRouterLink extends SatBreadcrumbsItemBase {
  /** The route to navigate to, compatible with Angular Router's routerLink directive. */
  routerLink: NonNullable<RouterLink['routerLink']>;
  /** Optional query parameters to include in the navigation. */
  queryParams?: RouterLink['queryParams'];
}

/**
 * Union type representing all possible breadcrumb item variants.
 *
 * This type encompasses all supported breadcrumb item configurations:
 * - `SatBreadcrumbsItemBase`: Non-clickable items (typically current page)
 * - `SatBreadcrumbsItemWithHref`: Items with standard HTML anchor navigation
 * - `SatBreadcrumbsItemWithRouterLink`: Items using Angular Router navigation
 *
 * Use this type when defining arrays of breadcrumb items or component inputs
 * that should accept any valid breadcrumb item configuration.
 *
 * @example
 * ```typescript
 * const breadcrumbItems: SatBreadcrumbsItem[] = [
 *   { label: 'Home', routerLink: '/' },
 *   { label: 'Products', href: '/products' },
 *   { label: 'Current Product' } // No navigation (current page)
 * ];
 * ```
 */
export type SatBreadcrumbsItem =
  | SatBreadcrumbsItemBase
  | SatBreadcrumbsItemWithHref
  | SatBreadcrumbsItemWithRouterLink;

/**
 * Internal type that extends the breadcrumb items with flags to indicate if they are links and if they use router navigation.
 */
type BreadcrumbsItemWithFlags =
  | (SatBreadcrumbsItemWithHref & { isRouter: false; isLink: true })
  | (SatBreadcrumbsItemWithRouterLink & { isRouter: true; isLink: true })
  | (SatBreadcrumbsItemBase & { isRouter: false; isLink: false });

/**
 * The Breadcrumbs component displays a navigation path, allowing users to easily navigate back to previous pages.
 * It supports truncation of items into a menu when the available space is insufficient.
 */
@Component({
  selector: 'sat-breadcrumbs',
  templateUrl: './breadcrumbs.html',
  styleUrl: './breadcrumbs.scss',
  imports: [
    MatButtonModule,
    MatMenuModule,
    MatIconModule,
    TranslatePipe,
    RouterLink,
    RouterLinkWithHref,
  ],
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatBreadcrumbs implements OnDestroy {
  /**
   * Input signal for the breadcrumb items.
   */
  readonly items = input<BreadcrumbsItemWithFlags[], SatBreadcrumbsItem[]>([], {
    transform: items =>
      items.map(item => {
        if ('routerLink' in item && item.routerLink) {
          return { ...item, isRouter: true, isLink: true };
        } else if ('href' in item && item.href) {
          return { ...item, isRouter: false, isLink: true };
        } else {
          return { ...item, isRouter: false, isLink: false };
        }
      }),
  });

  /**
   * Signal for the items currently displayed in the breadcrumbs.
   * @internal
   */
  readonly visibleItems = linkedSignal<BreadcrumbsItemWithFlags[], BreadcrumbsItemWithFlags[]>({
    source: this.items,
    computation: items => [...(items || [])],
  });

  /**
   * Computed signal for the hidden items (collapsed into the menu).
   * @internal
   */
  readonly hiddenItems = computed<BreadcrumbsItemWithFlags[]>(() => {
    const allItems = this.items() ?? [];
    const visibleItems = this.visibleItems();
    return allItems.filter(item => !visibleItems.includes(item));
  });

  private readonly _element = inject<ElementRef<HTMLElement>>(ElementRef);

  /**
   * Last registered width of the component
   */
  private width = 0;

  /**
   * To determine if the last item in the breadcrumbs is the current page.
   * @internal
   */
  readonly hasCurrentPage = computed(() => {
    // If the last item does not have an href or routerLink, it is considered the current page.
    const items = this.items();
    if (!items || items.length <= 0) {
      return false;
    }
    const lastItem = items[items.length - 1];
    return !lastItem.isLink && !lastItem.isRouter;
  });

  private truncationTimeout?: ReturnType<typeof setTimeout>;
  private resizeTimeout?: ReturnType<typeof setTimeout>;

  private readonly resizeObserver = new ResizeObserver(entries => {
    for (const entry of entries) {
      this.debounceResize(entry.contentRect.width);
    }
  });

  constructor() {
    afterNextRender({
      read: () => {
        this.resizeObserver.observe(this._element.nativeElement);
      },
    });
  }

  ngOnDestroy() {
    this.resizeObserver?.disconnect();
    clearTimeout(this.resizeTimeout);
    clearTimeout(this.truncationTimeout);
  }

  /**
   * The resize event can fire frequently during user interactions, so we debounce it to trigger
   * only after resizing or layout changes have stopped. This prevents flickering effects during resizing.
   */
  private debounceResize(width: number): void {
    clearTimeout(this.resizeTimeout);
    this.resizeTimeout = setTimeout(() => {
      if (width > this.width) {
        this.visibleItems.set([...(this.items() || [])]);
      }
      this.width = width;
      this.debounceTruncation();
    }, 100);
  }

  /**
   * Recursively manages breadcrumb item overflow.
   * Uses a 0ms timeout to run immediately after the next render cycle,
   * ensuring the component measures its size accurately for each recursion step.
   */
  private debounceTruncation(): void {
    clearTimeout(this.truncationTimeout);
    this.truncationTimeout = setTimeout(() => {
      if (!this._element) {
        return;
      }

      if (this._element.nativeElement.scrollWidth <= this._element.nativeElement.offsetWidth) {
        // It's not overflowing
        return;
      }

      /**
       * When there are more than two visible items, or when Breadcrumbs have current location and more than
       * three visible items, the item to hide is the second one, because for most users the first item is of
       * more importance, following in importance the last item, and they are likely to want to return to it.
       */
      const visibleItems = this.visibleItems();
      const maximumVisibleItems = this.hasCurrentPage() ? 3 : 2;
      const itemsToDisplay =
        visibleItems.length > maximumVisibleItems
          ? [visibleItems[0], ...visibleItems.slice(2)]
          : visibleItems.slice(1);

      if (itemsToDisplay.length !== visibleItems.length) {
        this.visibleItems.set(itemsToDisplay);

        if (itemsToDisplay.length) {
          // If there are still items to display, we need to check again for overflow.
          this.debounceTruncation();
        }
      }
    }, 0);
  }
}
